solution:
# 分数段分级:0-59 为 E,60 起依次 D/C/B/A
score = int(input())
if score >= 90:
    print("A")
elif score >= 80:
    print("B")
elif score >= 70:
    print("C")
elif score >= 60:
    print("D")
else:
    print("E")

tutorial.code:
score = 85
if score >= 90:
    print("A")
elif score >= 80:
    print("B")     # 85>=90 不成立,但 85>=80 成立,输出 B
else:
    print("E")

# 从高往低判断,否则会被低分条件提前拦住
if score >= 90:
    print("A")
elif score >= 80:
    print("B")
elif score >= 70:
    print("C")
elif score >= 60:
    print("D")
else:
    print("E")

solution:
# 闰年:能被4整除且(不能被100整除或能被400整除)
year = int(input())
if (year % 4 == 0 and year % 100 != 0) or year % 400 == 0:
    print("yes")
else:
    print("no")

